import { test, expect } from '@playwright/test';

test.describe('Профиль — гость: нет входа/экранов с паролем', () => {
  test('PR-01 Гость: на /phone и /register нет входа по паролю, экраны пароля не открываются #6a86f7f9 @prod-safe', async ({ page }) => {
    // 1. Открыть `/phone`, затем `/register` — найти ссылки «כניסה/הרשמה עם מייל וסיסמה».
    for (const route of ['/phone', '/register']) {
      await page.goto(route);
      await expect(page.getByRole('heading').or(page.getByText(/כניסה דרך מספר נייד|יצירת חשבון/)).first()).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText('כניסה עם מייל וסיסמה')).toHaveCount(0);
      await expect(page.getByText('הרשמה עם מייל וסיסמה')).toHaveCount(0);
      await expect(page.getByText(/מייל וסיסמה/)).toHaveCount(0);
      await expect(page.locator('body')).not.toContainText('סיסמה');
    }

    // 2. По очереди открыть экраны пароля — ни один не открывается (Unmatched Route).
    for (const route of ['/forgot-password', '/change-password', '/reset-password', '/set-password', '/login-email']) {
      await page.goto(route);
      await expect(page.getByText('Unmatched Route')).toBeVisible();
      await expect(page.getByText('Page could not be found.')).toBeVisible();
    }
  });
});
